cards.solution:
const pesan = document.querySelector("#pesan");
const kartu = document.querySelectorAll(".kartu");
pesan.classList.remove("tersembunyi");
kartu[1].classList.remove("terpilih");
kartu[2].classList.add("terpilih");
console.log(pesan.classList.contains("tersembunyi"));
console.log(kartu[1].className);
console.log(kartu[2].className);
